   <a class="skip-link" href="#main-content">Skip to main content</a>

   <main id="main-content">
     <section class="card" aria-labelledby="page-title">
       <p class="eyebrow">Preferences</p>
       <h1 id="page-title">Stay in the loop</h1>
       <p class="intro">Choose how we should send updates about your account, product news, and important reminders.</p>

       <form id="notification-form" novalidate>
         <p class="required-note"><span class="required-marker" aria-hidden="true">*</span> Required field</p>

         <div class="form-field">
           <fieldset aria-describedby="notification-help notification-error">
             <legend>How do you prefer to receive notifications? <span class="required-marker" aria-hidden="true">*</span></legend>
             <p id="notification-help" class="field-help">Select one notification method.</p>
             <p id="notification-error" class="field-help" hidden>Error: Choose one notification method.</p>

             <div class="radio-options">
               <div class="radio-option">
                 <input id="notification-email" type="radio" name="notification-preference" value="Email" required>
                 <label for="notification-email">Email</label>
               </div>

               <div class="radio-option">
                 <input id="notification-sms" type="radio" name="notification-preference" value="SMS" required>
                 <label for="notification-sms">SMS</label>
               </div>

               <div class="radio-option">
                 <input id="notification-push" type="radio" name="notification-preference" value="Push Notifications" required>
                 <label for="notification-push">Push Notifications</label>
               </div>
             </div>
           </fieldset>
         </div>

         <button type="submit">Save preference</button>
         <p id="form-status" class="status" aria-live="polite"></p>
       </form>
     </section>
   </main>

   <script>
     const form = document.querySelector("#notification-form");
     const radios = Array.from(document.querySelectorAll('input[name="notification-preference"]'));
     const error = document.querySelector("#notification-error");
     const status = document.querySelector("#form-status");

     function setRadioValidity(isValid) {
       error.hidden = isValid;
       radios.forEach((radio) => {
         radio.setAttribute("aria-invalid", String(!isValid));
       });
     }

     radios.forEach((radio) => {
       radio.addEventListener("change", () => {
         setRadioValidity(true);
         status.textContent = "";
       });
     });

     form.addEventListener("submit", (event) => {
       event.preventDefault();

       const selected = radios.find((radio) => radio.checked);

       if (!selected) {
         setRadioValidity(false);
         radios[0].focus();
         status.textContent = "";
         return;
       }

       setRadioValidity(true);
       status.textContent = `Preference saved: ${selected.value}.`;
     });
   </script>
 </body>
