      border-radius: 999px;
      padding: 0.95rem 1.25rem;
      color: #ffffff;
      background: var(--primary);
      font: inherit;
      font-weight: 800;
      cursor: pointer;
      box-shadow: 0 14px 30px rgba(36, 87, 214, 0.24);
    }

    button:hover {
      background: var(--primary-dark);
    }

    button:focus-visible {
      outline: 3px solid var(--ring);
      outline-offset: 4px;
    }

    .status {
      min-height: 1.5rem;
      margin: 1rem 0 0;
      color: var(--primary-dark);
      font-weight: 700;
      line-height: 1.5;
    }

