 <!DOCTYPE html>
 <html lang="en">
 <head>
   <meta charset="UTF-8">
   <meta name="viewport" content="width=device-width, initial-scale=1.0">
   <title>Notification Preferences</title>
   <style>
     :root {
       color-scheme: light;
       --background: #f4f7fb;
       --surface: #ffffff;
       --text: #172033;
       --muted: #5e6b80;
       --primary: #2457d6;
       --primary-dark: #1d45aa;
       --border: #d7deea;
       --ring: #7aa2ff;
       --shadow: 0 24px 70px rgba(31, 42, 68, 0.14);
     }

     * {
       box-sizing: border-box;
     }

     body {
       min-height: 100vh;
       margin: 0;
       font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
       color: var(--text);
       background:
         radial-gradient(circle at top left, rgba(36, 87, 214, 0.16), transparent 34rem),
         linear-gradient(135deg, #f8fbff 0%, var(--background) 100%);
     }

     .skip-link {
       position: absolute;
       top: 1rem;
       left: 1rem;
       z-index: 10;
       transform: translateY(-150%);
       border-radius: 999px;
       padding: 0.75rem 1rem;
       color: #ffffff;
       background: var(--primary);
       font-weight: 700;
       text-decoration: none;
     }

     .skip-link:focus {
       transform: translateY(0);
       outline: 3px solid var(--ring);
       outline-offset: 3px;
     }

     main {
       display: grid;
       min-height: 100vh;
       place-items: center;
       padding: 2rem 1rem;
     }

     .card {
       width: min(100%, 35rem);
       border: 1px solid rgba(215, 222, 234, 0.8);
       border-radius: 1.5rem;
       padding: clamp(1.5rem, 5vw, 2.5rem);
       background: rgba(255, 255, 255, 0.92);
       box-shadow: var(--shadow);
     }

     .eyebrow {
       margin: 0 0 0.75rem;
       color: var(--primary);
       font-size: 0.78rem;
       font-weight: 800;
       letter-spacing: 0.08em;
       text-transform: uppercase;
     }

     h1 {
       margin: 0;
       font-size: clamp(2rem, 8vw, 3rem);
       line-height: 1.05;
       letter-spacing: -0.04em;
     }

     .intro {
       max-width: 28rem;
       margin: 1rem 0 2rem;
       color: var(--muted);
       font-size: 1.05rem;
       line-height: 1.6;
     }

     .form-field {
       margin: 0;
     }

     .form-field fieldset {
       margin: 0;
       border: 0;
       padding: 0;
     }

     legend {
       margin-bottom: 0.5rem;
       padding: 0;
       font-size: 1.2rem;
       font-weight: 800;
       line-height: 1.3;
     }

     .required-note,
     .field-help {
       color: var(--muted);
       font-size: 0.95rem;
       line-height: 1.5;
     }

     .required-note {
       margin: 0 0 1.5rem;
     }

     .field-help {
       margin: 0 0 1rem;
     }

     .required-marker {
       color: #b42318;
     }

     .radio-options {
       display: grid;
       gap: 0.75rem;
       margin-top: 1rem;
     }

     .radio-option {
       position: relative;
     }

     .radio-option input {
       position: absolute;
       inset-block-start: 1.25rem;
       inset-inline-start: 1.25rem;
       width: 1.25rem;
       height: 1.25rem;
       margin: 0;
       opacity: 0;
     }

     .radio-option label {
       display: flex;
       min-height: 3.75rem;
       align-items: center;
       gap: 0.9rem;
       border: 1px solid var(--border);
       border-radius: 1rem;
       padding: 1rem 1.1rem;
       color: var(--text);
       background: #ffffff;
       font-weight: 700;
       cursor: pointer;
       transition: border-color 160ms ease, box-shadow 160ms ease, transform 160ms ease;
     }

     .radio-option label::before {
       width: 1.2rem;
       height: 1.2rem;
       flex: 0 0 auto;
       border: 2px solid #8090a8;
       border-radius: 50%;
       background: #ffffff;
       box-shadow: inset 0 0 0 0.25rem #ffffff;
       content: "";
     }

     .radio-option input:checked + label {
       border-color: var(--primary);
       box-shadow: 0 12px 32px rgba(36, 87, 214, 0.16);
     }

     .radio-option input:checked + label::before {
       border-color: var(--primary);
       background: var(--primary);
     }

     .radio-option input:focus-visible + label {
       outline: 3px solid var(--ring);
       outline-offset: 3px;
     }

     .radio-option label:hover {
       border-color: #9ba9bf;
       transform: translateY(-1px);
     }

     button {
       width: 100%;
       margin-top: 1.75rem;
       border: 0;
       border-radius: 999px;
       padding: 0.95rem 1.25rem;
       color: #ffffff;
       background: var(--primary);
       font: inherit;
       font-weight: 800;
       cursor: pointer;
       box-shadow: 0 14px 30px rgba(36, 87, 214, 0.24);
     }

     button:hover {
       background: var(--primary-dark);
     }

     button:focus-visible {
       outline: 3px solid var(--ring);
       outline-offset: 4px;
     }

     .status {
       min-height: 1.5rem;
       margin: 1rem 0 0;
       color: var(--primary-dark);
       font-weight: 700;
       line-height: 1.5;
     }

     @media (prefers-reduced-motion: reduce) {
       *,
       *::before,
       *::after {
         scroll-behavior: auto !important;
         transition-duration: 0.01ms !important;
         animation-duration: 0.01ms !important;
         animation-iteration-count: 1 !important;
       }
     }

     @media (forced-colors: active) {
       .card,
       .radio-option label,
       button {
         border: 1px solid CanvasText;
         box-shadow: none;
       }

       .radio-option input:checked + label {
         outline: 2px solid Highlight;
       }

       .radio-option label::before {
         forced-color-adjust: auto;
       }
     }
